SELECT COUNT(*) FROM medico
WHERE no_personal = #{noPersonal}
  AND id_medico  != #{idMedico}

SELECT COUNT(*) FROM medico
WHERE cedula_profesional = #{cedulaProfesional}
  AND id_medico         != #{idMedico}

