UPDATE paciente
SET id_medico = #{idMedicoNuevo}
WHERE id_medico = #{idMedicoBaja}
    AND estatus = 1

UPDATE medico
SET fotografia = #{fotografia}
WHERE id_medico = #{idMedico}
